    const v = bl[bl.type] || {};
    const txt = (v.rich_text || []).map(t => t.plain_text || '').join('');
    if (!txt) return '';
    if (bl.type.startsWith('heading')) return '## ' + txt;
    if (bl.type === 'bulleted_list_item') return '- ' + txt;
    if (bl.type === 'numbered_list_item') return '1. ' + txt;
